class Solution {
  public int[] rotateElements(int[] nums, int k) {
    int n = nums.length, m = 0;
    int[] vals = new int[n];
    for (int v : nums) if (v >= 0) vals[m++] = v;
    int[] res = nums.clone();
    if (m == 0) return res;
    int shift = k % m, p = 0;
    for (int i = 0; i < n; i++) if (nums[i] >= 0) res[i] = vals[(p++ + shift) % m];
    return res;
  }
}
